// Each addition contains a lesson, a concrete keyboard lab and its own original study.
const additions = [
  { id:'legato',stage:1,title:'Unir sin apretar',category:'Articulación',pattern:'legato',study:'Un hilo de sonido',bpm:56,
    paragraphs:['Legato significa conectar los sonidos. Empieza con dos notas vecinas: mientras una termina, la siguiente empieza. El movimiento continúa sin mantener tensión en la mano. Staccato, en cambio, separa las notas con una liberación breve y flexible.','Practica la misma frase primero ligada y después separada, sin pedal. Escucha los huecos y las superposiciones. La pantalla indica qué notas tocar; el resultado sonoro y el gesto necesitan tu atención.'],
    lab:['Toca Do–Re–Mi–Fa–Sol y vuelve a Do, sin pedal.','Repite con una separación audible entre notas. Mantén el mismo pulso.','Graba ambas versiones y comprueba si se distingue la articulación.'],
    question:'¿Qué describe mejor el legato?',answers:['Tocar todas las notas fuertes','Conectar los sonidos de una frase','Usar siempre el pedal'],correct:1,explanation:'El legato conecta sonidos; puede trabajarse sin pedal.',target:'Distinguir al oído ligado y separado, sin rigidez.' },
  { id:'major-scale',stage:1,title:'La primera escala completa',category:'Escalas y digitación',pattern:'major',study:'El camino de Do mayor',bpm:52,
    paragraphs:['Do mayor recorre Do–Re–Mi–Fa–Sol–La–Si–Do. Su patrón de tonos y semitonos es tono, tono, semitono, tono, tono, tono, semitono. Las teclas blancas permiten reconocer ese patrón.','Para una octava ascendente con la derecha puedes usar 1–2–3–1–2–3–4–5; con la izquierda, 5–4–3–2–1–3–2–1. Al bajar inviertes la secuencia. Prepara el cambio de pulgar con suavidad: el brazo acompaña, sin giros bruscos.'],
    lab:['Practica una octava con cada mano a 52 BPM.','Di el nombre de cada nota al tocarla.','Junta las manos solo cuando ambas recorran la escala cómodamente.'],
    question:'¿Dónde están los semitonos de Do mayor?',answers:['Do–Re y Sol–La','Re–Mi y La–Si','Mi–Fa y Si–Do'],correct:2,explanation:'Mi–Fa y Si–Do están a un semitono.',target:'Una octava regular por mano con digitación estable.' },
  { id:'subdivision',stage:2,title:'Entre un pulso y el siguiente',category:'Ritmo',pattern:'eighths',study:'Dos pasos por latido',bpm:60,
    paragraphs:['Subdividir permite colocar varias notas dentro de un pulso. En 4/4, dos corcheas regulares ocupan lo mismo que una negra. Cuenta «uno y dos y tres y cuatro y» sin cambiar la velocidad del pulso.','Alterna un compás de negras con otro de corcheas. El metrónomo mantiene las negras; tú colocas las notas intermedias. La regularidad vale más que acelerar.'],
    lab:['Da palmas a negras durante cuatro pulsos.','Añade una palma entre cada pareja de pulsos.','Toca el estudio alternando notas largas y subdivisiones.'],
    question:'En 4/4, ¿cuántas corcheas equivalen a una negra?',answers:['Dos','Tres','Cuatro'],correct:0,explanation:'Dos corcheas regulares completan una negra.',target:'Cambiar de negras a corcheas sin acelerar el pulso.' },
  { id:'syncopation',stage:2,title:'Acentos que se adelantan',category:'Ritmo',pattern:'syncopation',study:'Un paso a contratiempo',bpm:54,
    paragraphs:['Una síncopa prolonga un sonido desde una parte débil hacia otra más fuerte. Un contratiempo coloca un ataque en la parte débil tras un silencio en la fuerte. Se parecen al oído, pero no son exactamente lo mismo.','Conserva el pulso con la izquierda mientras la derecha entra entre pulsos. Cuenta en voz alta. Antes de juntarlas, canta el ritmo de la derecha sobre las palmas de la izquierda.'],
    lab:['Cuenta «uno y dos y» manteniendo negras con una mano.','Ataca con la derecha en los «y».','Repite despacio sin desplazar los pulsos de la izquierda.'],
    question:'¿Qué ayuda a mantener una síncopa estable?',answers:['Cambiar el tempo en cada ataque','Conservar una referencia de pulso','Acentuar todas las notas igual'],correct:1,explanation:'Una referencia estable permite situar los ataques desplazados.',target:'Entradas desplazadas sobre una izquierda regular.' },
  { id:'key-signatures',stage:2,title:'Tonalidades y armaduras',category:'Teoría',pattern:'gmajor',study:'Una ventana a Sol mayor',bpm:56,
    paragraphs:['La tonalidad organiza las notas alrededor de una tónica. La armadura indica alteraciones que se aplican durante la pieza, salvo cambios escritos. Sol mayor tiene un sostenido: Fa♯. Fa mayor tiene un bemol: Si♭.','Compara Do mayor y Sol mayor tocando sus escalas. Escucha la llegada a la tónica. En una partitura, una alteración accidental suele afectar a la misma nota y octava durante el resto del compás.'],
    lab:['Nombra las notas de Sol mayor antes de tocarlas.','Localiza todos los Fa♯ del estudio.','Termina la frase en Sol y escucha la sensación de reposo.'],
    question:'¿Qué alteración tiene Sol mayor?',answers:['Si bemol','Do sostenido','Fa sostenido'],correct:2,explanation:'Sol mayor utiliza Fa♯ en su armadura.',target:'Reconocer tónica y Fa♯ sin depender de los colores.' },
  { id:'inversions',stage:2,title:'Un acorde, varias posiciones',category:'Armonía',pattern:'inversions',study:'El acorde cambia de lugar',bpm:48,
    paragraphs:['Do–Mi–Sol, Mi–Sol–Do y Sol–Do–Mi contienen las mismas clases de notas. Cambia la nota del bajo: estado fundamental, primera inversión y segunda inversión.','Las inversiones permiten conectar acordes con movimientos pequeños. Conserva notas comunes cuando sea cómodo y escucha cómo cambia el apoyo del bajo. La digitación depende del contexto: elige una que permita enlazar.'],
    lab:['Toca las tres posiciones de Do mayor por separado.','Arpegia cada posición y después toca el acorde completo.','Conecta Do, Fa y Sol buscando movimientos cercanos.'],
    question:'En Mi–Sol–Do, ¿qué inversión de Do mayor aparece?',answers:['Primera inversión','Segunda inversión','Estado fundamental'],correct:0,explanation:'Mi es la tercera del acorde y está en el bajo: primera inversión.',target:'Reconocer el acorde aunque cambie su posición.' },
  { id:'ear-intervals',stage:2,title:'Escuchar una distancia',category:'Oído',pattern:'intervals',study:'Preguntas de dos notas',bpm:50,listen:{notes:[60,67],together:false},
    paragraphs:['Entrenar el oído une nombres, sonidos y movimientos. Compara una tercera mayor, Do–Mi, con una quinta justa, Do–Sol. Canta la nota de llegada antes de tocarla.','Escucha el ejemplo sin mirar el teclado. Después busca sus notas. Cambia el punto de partida: reconocer un intervalo consiste en reconocer una relación, no solo dos teclas memorizadas.'],
    lab:['Escucha el ejemplo y canta ambas notas.','Busca una tercera mayor y una quinta desde Do.','Repite desde Sol y compara la sensación de cada intervalo.'],
    question:'¿Qué intervalo suena en el ejemplo Do–Sol?',answers:['Una segunda menor','Una quinta justa','Una tercera mayor'],correct:1,explanation:'De Do a Sol hay una quinta justa: siete semitonos.',target:'Cantar y reconocer terceras mayores y quintas desde varias notas.' },
  { id:'minor-scales',stage:3,title:'Tres formas del modo menor',category:'Escalas y teoría',pattern:'minor',study:'Tres colores de La menor',bpm:56,
    paragraphs:['La menor natural usa La–Si–Do–Re–Mi–Fa–Sol–La. La menor armónica eleva el séptimo grado: Sol♯. La menor melódica clásica eleva sexto y séptimo al subir y suele volver a la forma natural al bajar.','No conviertas estas formas en reglas rígidas para toda música: la práctica armónica y melódica decide qué grados se alteran. Escucha especialmente cómo Sol♯ conduce hacia La.'],
    lab:['Toca La menor natural y después armónica.','Canta el movimiento Sol♯–La.','Compara la forma melódica ascendente con la natural descendente.'],
    question:'¿Qué cambia en La menor armónica respecto a la natural?',answers:['Do se vuelve sostenido','Fa se vuelve sostenido','Sol se vuelve sostenido'],correct:2,explanation:'El séptimo grado se eleva: Sol pasa a Sol♯.',target:'Distinguir las tres formas y su sonido.' },
  { id:'extended-arpeggios',stage:3,title:'Arpegios que recorren el teclado',category:'Técnica',pattern:'wide-arpeggio',study:'Un arco de dos octavas',bpm:48,
    paragraphs:['Un arpegio largo distribuye un acorde a lo largo de varias posiciones. El desplazamiento del brazo prepara la siguiente zona; la mano no debe quedarse anclada intentando alcanzar todas las notas.','Divide el recorrido en grupos, trabaja los enlaces y vuelve a reunirlo. Acentúa temporalmente distintas notas para descubrir irregularidades. Después elimina esos acentos del resultado musical.'],
    lab:['Localiza las notas del acorde en dos octavas.','Practica solo los enlaces entre posiciones.','Reúne el arpegio lento, con un sonido uniforme.'],
    question:'¿Qué facilita un arpegio que cambia de posición?',answers:['Preparar el desplazamiento con el brazo','Mantener la mano estirada al máximo','Sujetar siempre el pulgar'],correct:0,explanation:'El desplazamiento coordinado evita intentar abarcarlo todo con una extensión fija.',target:'Enlaces fluidos entre posiciones, sin forzar la extensión.' },
  { id:'accompaniment',stage:3,title:'Sostener sin tapar',category:'Coordinación',pattern:'alberti',study:'Un bajo que acompaña',bpm:58,
    paragraphs:['Un acompañamiento sirve a una melodía. El bajo de Alberti despliega un acorde con un patrón frecuente de grave–agudo–medio–agudo. Su regularidad no debe borrar la dirección de la frase superior.','Aprende el acompañamiento hasta reconocer su forma armónica. Añade la melodía lentamente y escucha desde fuera: deberías poder seguirla sin esfuerzo. MIDI muestra ataques, pero el equilibrio final se juzga escuchando.'],
    lab:['Practica el patrón de la izquierda sin la melodía.','Canta la melodía mientras tocas el bajo.','Junta ambas y graba si la melodía sigue destacando.'],
    question:'¿Qué debe guiar el volumen del acompañamiento?',answers:['Tocar siempre más fuerte que la derecha','Dejar que la melodía se perciba claramente','Cambiar de acorde en cada nota'],correct:1,explanation:'El acompañamiento crea apoyo sin ocultar la línea principal.',target:'Melodía audible por encima de un patrón regular.' },
  { id:'voicing',stage:3,title:'Una voz dentro del acorde',category:'Sonido y expresión',pattern:'voicing',study:'La nota que cuenta la historia',bpm:46,
    paragraphs:['Voicing significa equilibrar las notas que suenan juntas. Si la melodía está arriba, intenta que esa nota destaque mientras las interiores acompañan. No todas las notas necesitan la misma intensidad.','Primero toca la melodía sola; después añade las otras notas a menor intensidad. Escucha una grabación. Encontrar todas las teclas es solo el comienzo: la calidad del balance no se obtiene de una puntuación de aciertos.'],
    lab:['Extrae y canta la voz superior del estudio.','Añade las notas inferiores con un sonido más discreto.','Alterna una versión equilibrada y otra deliberadamente plana.'],
    question:'¿Qué describe el voicing?',answers:['Cambiar la afinación del piano','Leer solo la clave de fa','Equilibrar las voces o notas simultáneas'],correct:2,explanation:'El voicing organiza qué línea o nota destaca en la textura.',target:'Hacer reconocible la voz superior sin endurecer el acorde.' },
  { id:'musical-form',stage:3,title:'Escuchar la arquitectura',category:'Análisis',pattern:'aba',study:'Salir y volver: A–B–A',bpm:60,
    paragraphs:['La forma ayuda a orientarse en una pieza. Una estructura A–B–A presenta una idea, contrasta con otra y vuelve a la primera. Una frase también tiene dirección, puntos de apoyo y cierre.','Localiza semejanzas y diferencias antes de memorizar. En el estudio, los primeros cuatro compases forman A, los cuatro siguientes B y después vuelve A. Decide cómo mostrar el regreso con el sonido.'],
    lab:['Escucha el estudio y marca dónde empieza B.','Practica cada sección por separado.','Une las tres secciones conservando sus contrastes.'],
    question:'¿Qué representa la última A en una forma A–B–A?',answers:['El regreso de la idea inicial','Un cambio obligatorio de tonalidad','Una repetición de todas las notas de B'],correct:0,explanation:'La última A recupera el material de la sección inicial.',target:'Reconocer secciones y dar dirección a cada frase.' },
  { id:'polyphony',stage:4,title:'Dos líneas con vida propia',category:'Polifonía',pattern:'counterpoint',study:'Dos voces que se escuchan',bpm:50,
    paragraphs:['En una textura polifónica conviven líneas con dirección propia. Aprende cada voz como si fuera una melodía completa, con su respiración y sus apoyos. No basta con tratar una mano como relleno.','Toca una voz y canta la otra. Después cambia los papeles. Al reunirlas, comprueba que ambas siguen siendo reconocibles y que los finales de nota no se mezclan por accidente.'],
    lab:['Canta cada línea por separado.','Toca la izquierda y canta la derecha; después invierte.','Reúne las voces sin pedal y revisa las duraciones.'],
    question:'¿Qué ejercicio ayuda a independizar dos voces?',answers:['Ignorar siempre la voz grave','Tocar una y cantar la otra','Usar pedal durante toda la pieza'],correct:1,explanation:'Cantar una línea mientras se toca otra refuerza su independencia auditiva.',target:'Seguir dos melodías simultáneas con claridad.' },
  { id:'two-three',stage:4,title:'Dos contra tres',category:'Polirritmia',pattern:'two-three',study:'Dos caminos, un encuentro',bpm:44,
    paragraphs:['Una relación 2:3 coloca dos ataques regulares de una voz en el mismo tiempo que tres de otra. Ambas coinciden al principio y al final del grupo. Una cuadrícula de seis subdivisiones ayuda a ubicar sus ataques.','En este estudio la izquierda toca dos notas por cada grupo de dos negras y la derecha tres. Da primero el ritmo con las manos fuera del teclado. Después transfiérelo a dos notas cómodas.'],
    lab:['Divide un grupo en seis partes: una mano ataca en 1 y 4; la otra en 1, 3 y 5.','Practica cada patrón por separado.','Junta las manos manteniendo el encuentro al inicio de cada grupo.'],
    question:'¿Cuántas subdivisiones comunes sirven para estudiar 2:3?',answers:['Cuatro','Cinco','Seis'],correct:2,explanation:'Seis es el mínimo común múltiplo de dos y tres.',target:'Mantener ambos ritmos regulares sin convertirlos en una alternancia desigual.' },
  { id:'chromaticism',stage:4,title:'El teclado en semitonos',category:'Técnica y teoría',pattern:'chromatic',study:'Una escalera cromática',bpm:52,
    paragraphs:['La escala cromática recorre todos los semitonos. Una alteración puede pertenecer a la tonalidad, aproximar otra nota o crear tensión cromática. Leer su función ayuda a anticipar el movimiento.','Empieza con una octava y decide una digitación cómoda. Busca desplazamiento lateral pequeño y un sonido continuo. Cambia de dirección sin perder el pulso.'],
    lab:['Toca doce semitonos desde Do hasta el siguiente Do.','Repite descendiendo, sin mirar cada dedo.','Practica el estudio identificando qué notas son aproximaciones cromáticas.'],
    question:'¿Qué distancia separa dos notas consecutivas de una escala cromática?',answers:['Un semitono','Un tono','Una tercera'],correct:0,explanation:'La escala cromática avanza de semitono en semitono.',target:'Recorrido cromático regular en ambos sentidos.' },
  { id:'modulation',stage:4,title:'Cambiar de centro',category:'Armonía',pattern:'modulation',study:'De Do a Sol',bpm:50,
    paragraphs:['Modular significa establecer una nueva tonalidad, no solo tocar una nota alterada. Una cadencia y la aparición de una sensible nueva pueden ayudar a confirmar el cambio.','El estudio parte de Do mayor y se dirige a Sol mayor. Escucha el Fa♯ y el acorde de Re mayor como señales del nuevo centro. Reduce la textura a sus acordes para comprender el recorrido.'],
    lab:['Toca Do–Fa–Sol–Do para fijar el primer centro.','Después toca Sol–Do–Re–Sol con Fa♯ en Re mayor.','Escucha dónde la frase empieza a descansar en Sol.'],
    question:'¿Qué define mejor una modulación?',answers:['Tocar cualquier nota negra','Establecer una tonalidad nueva','Aumentar el tempo'],correct:1,explanation:'Una modulación establece otro centro tonal; una alteración aislada no basta.',target:'Escuchar y explicar el cambio de centro tonal.' },
  { id:'sight-reading',stage:4,title:'Leer hacia delante',category:'Lectura a primera vista',pattern:'sight',study:'Una frase desconocida',bpm:48,
    paragraphs:['Antes de leer, observa tonalidad, compás, textura y posibles cambios de posición. Elige un tempo que permita continuar. En una primera lectura, la continuidad suele importar más que corregir cada detalle al instante.','Lee pequeños grupos y anticipa la siguiente posición mientras suena la actual. Para entrenar lectura convencional necesitas el pentagrama original: la vista de notas descendentes ayuda a practicar, pero no sustituye esa lectura.'],
    lab:['Usa una partitura sencilla de la biblioteca y obsérvala un minuto sin tocar.','Lee un fragmento nuevo lentamente, manteniendo el pulso.','Anota dos dificultades y trabaja después esos puntos por separado.'],
    question:'¿Qué conviene hacer antes de leer una partitura nueva?',answers:['Memorizarla completa','Buscar el tempo más rápido','Observar tonalidad, compás y cambios de posición'],correct:2,explanation:'Una preparación breve permite anticipar las principales decisiones de lectura.',target:'Continuidad en una lectura sencilla con anticipación visual.' },
  { id:'three-four',stage:5,title:'Tres contra cuatro',category:'Polirritmia avanzada',pattern:'three-four',study:'Un mismo tiempo, dos medidas',bpm:40,
    paragraphs:['En una relación 3:4 caben tres ataques de una voz donde la otra realiza cuatro. Doce subdivisiones comunes permiten colocarlos exactamente antes de sentir el grupo de manera más global.','La izquierda del estudio realiza tres ataques en tres negras; la derecha, cuatro en ese mismo espacio. Empieza con notas repetidas y tempo muy lento. No añadas velocidad hasta que ambas capas sean regulares.'],
    lab:['Marca doce subdivisiones: ataques de tres en 1, 5 y 9; de cuatro en 1, 4, 7 y 10.','Da cada patrón con palmas y canta el otro.','Lleva el patrón al teclado manteniendo puntos de encuentro claros.'],
    question:'¿Cuál es la subdivisión común mínima para 3:4?',answers:['Doce','Siete','Seis'],correct:0,explanation:'Doce es el mínimo común múltiplo de tres y cuatro.',target:'Dos capas regulares sin acentos involuntarios en sus cruces.' },
  { id:'octaves',stage:5,title:'Octavas con libertad',category:'Técnica avanzada',pattern:'octaves',study:'Una melodía en octavas',bpm:42,
    paragraphs:['Las octavas reúnen dos notas con el mismo nombre a distancia de doce semitonos. La dificultad no consiste solo en abarcar la distancia, sino en desplazar la mano sin fijar una extensión rígida.','Trabaja grupos muy breves y libera entre ellos. Si el intervalo no resulta cómodo, toca la línea a una sola nota y revisa el gesto con un profesor. El estudio no exige alcanzar velocidad de concierto.'],
    lab:['Localiza la melodía con una sola nota.','Añade las octavas solo si la apertura resulta cómoda.','Practica dos o tres grupos y descansa antes de repetir.'],
    question:'¿Qué debe evitarse al estudiar octavas?',answers:['Empezar despacio','Mantener una extensión rígida continuamente','Practicar grupos breves'],correct:1,explanation:'La libertad de movimiento y la liberación entre grupos importan más que sostener una apertura fija.',target:'Desplazamientos cómodos y liberación entre grupos; revisión técnica externa.' },
  { id:'leaps',stage:5,title:'Llegar antes del salto',category:'Técnica avanzada',pattern:'leaps',study:'Islas en el teclado',bpm:44,
    paragraphs:['Un salto grande se prepara mirando y sintiendo la posición de llegada. Ensaya el traslado en silencio antes de añadir el ataque. La trayectoria debe ser suficiente y flexible, sin elevar el brazo innecesariamente.','Separa tres acciones: tocar, desplazarte y encontrar la nueva posición. Después reúne el gesto. La precisión repetida a tempo lento es más útil que acertar ocasionalmente a gran velocidad.'],
    lab:['Localiza cada posición de llegada sin sonido.','Toca y desplázate, haciendo una pausa antes del siguiente ataque.','Reduce la pausa gradualmente sin perder la orientación.'],
    question:'¿Qué facilita la precisión de un salto?',answers:['Mirar siempre la mano de salida','Acelerar el traslado sin preparar la llegada','Preparar la posición de destino'],correct:2,explanation:'La orientación hacia la llegada hace el movimiento más predecible.',target:'Llegadas preparadas y repetibles, con movimientos económicos.' },
  { id:'ornaments',stage:5,title:'Adornos con intención',category:'Estilo y técnica',pattern:'ornaments',study:'Una vuelta alrededor de la nota',bpm:46,
    paragraphs:['Trinos, mordentes y grupetos decoran una línea, pero su realización depende de la época, la edición y el contexto. No hay una velocidad o nota inicial universal para todos los adornos.','Extrae primero la nota principal y la resolución. Después añade el adorno sin romper el pulso de la frase. Este ejercicio escribe cada nota del adorno explícitamente; en archivos importados no se desarrollan automáticamente los símbolos.'],
    lab:['Toca la frase sin el adorno.','Añade las notas escritas lentamente y escucha su resolución.','Compara una edición comentada o una interpretación de referencia.'],
    question:'¿Qué determina la realización de un adorno?',answers:['El estilo, la época y el contexto','Una regla idéntica para toda la música','Solo el número de teclas negras'],correct:0,explanation:'Los adornos requieren una decisión informada por estilo y contexto.',target:'Integrar el adorno en la frase sin sacrificar la resolución.' },
  { id:'half-pedal',stage:5,title:'Más allá de encendido y apagado',category:'Pedal avanzado',pattern:'pedal',study:'Cambiar sin borrar la línea',bpm:44,
    paragraphs:['El medio pedal y los cambios parciales permiten variar cuánto sonido se conserva. Su efecto depende del instrumento, del registro y de la acústica. Aprende escuchando qué resonancias permanecen, no buscando una profundidad fija del pie.','Practica un cambio armónico lento: renueva el pedal después del ataque y escucha la limpieza del bajo. La app muestra un estado aproximado del pedal, pero no evalúa sus posiciones continuas ni la calidad de la mezcla.'],
    lab:['Toca el estudio sin pedal y reconoce sus cambios armónicos.','Añade cambios completos después de cada nueva armonía.','Explora después cambios parciales, comparando el sonido grabado.'],
    question:'¿Qué debe guiar un cambio parcial de pedal?',answers:['Un porcentaje fijo de recorrido','La resonancia y la claridad que escuchas','Mantener siempre todas las notas'],correct:1,explanation:'El oído determina qué resonancias conservar o limpiar en cada situación.',target:'Cambios armónicos claros y decisión de pedal basada en el sonido.' },
  { id:'rubato',stage:6,title:'Flexibilidad con dirección',category:'Interpretación',pattern:'rubato',study:'Respirar dentro del pulso',bpm:50,
    paragraphs:['Rubato es flexibilidad temporal con sentido musical. Puede afectar a una línea, a la frase o a la textura, según el estilo. Necesita una referencia de pulso interior y una dirección que el oyente pueda seguir.','Aprende primero la frase con ritmo estable. Después decide un punto de expansión y otro de recuperación. Para explorar libertad temporal utiliza el modo a tu ritmo: la puntuación del modo pulso no juzga la calidad del rubato.'],
    lab:['Toca una versión estricta con metrónomo.','Canta la frase y marca dónde necesita respirar.','Graba una versión flexible y compara si conserva dirección.'],
    question:'¿Qué modo permite explorar rubato sin penalización temporal?',answers:['Seguir el pulso a máxima velocidad','Cualquier modo evalúa automáticamente el rubato','A mi ritmo'],correct:2,explanation:'El modo a tu ritmo libera la temporización; la interpretación se revisa escuchando.',target:'Flexibilidad planificada que conserva continuidad y dirección.' },
  { id:'voice-leading',stage:6,title:'El recorrido de cada voz',category:'Armonía avanzada',pattern:'voice-leading',study:'Mover lo necesario',bpm:46,
    paragraphs:['La conducción de voces estudia cómo cada línea conecta una armonía con la siguiente. Las notas comunes y los movimientos conjuntos pueden crear continuidad; los saltos también tienen una función expresiva.','Reduce una textura a sus voces y canta cada recorrido. No conviertas la conducción en una regla mecánica de mínimo movimiento: el estilo, el bajo y la intención armónica deciden el resultado.'],
    lab:['Identifica las notas comunes entre cada pareja de acordes.','Canta una voz interior mientras tocas los acordes.','Escucha la resolución de notas con tendencia, especialmente sensibles.'],
    question:'¿Qué se observa al estudiar conducción de voces?',answers:['Cómo se mueve cada línea entre armonías','Solo la velocidad de los acordes','Únicamente las notas del bajo'],correct:0,explanation:'Se sigue el recorrido de cada voz a lo largo de la sucesión armónica.',target:'Explicar y escuchar el movimiento de voces interiores y exteriores.' },
  { id:'structural-analysis',stage:6,title:'De la partitura al discurso',category:'Análisis avanzado',pattern:'development',study:'Una idea que se transforma',bpm:54,
    paragraphs:['El análisis orienta decisiones de interpretación: motivos, secuencias, regiones tonales, tensiones y puntos culminantes. Un detalle local cobra sentido dentro del recorrido de toda la pieza.','El estudio transforma un motivo breve mediante secuencias y cambios de registro. Señala qué se conserva y qué cambia. Después planifica una curva de intensidad, sin confundir el punto más agudo con un clímax obligatorio.'],
    lab:['Reconoce el motivo inicial y sus transformaciones.','Marca reposos, tensiones y un punto de llegada.','Interpreta una versión que haga audibles esas relaciones.'],
    question:'¿Para qué sirve el análisis en la interpretación?',answers:['Para reemplazar la escucha','Para fundamentar decisiones musicales','Para imponer siempre la misma dinámica'],correct:1,explanation:'El análisis ayuda a relacionar decisiones locales con el recorrido de la obra.',target:'Un plan interpretativo argumentado y reconocible al escuchar.' },
  { id:'tone-colour',stage:6,title:'Una paleta de resonancias',category:'Sonido y estilo',pattern:'colour',study:'El mismo acorde, otro paisaje',bpm:42,
    paragraphs:['El color pianístico depende del equilibrio entre voces, articulación, registro, dinámica, pedal y acústica. En un digital también intervienen el timbre y su respuesta. Una misma tecla no ofrece todos los cambios de color de un instrumento acústico.','Mantén las notas y cambia una sola variable: balance, duración o pedal. Escucha desde una grabación, no solo desde la sensación de los dedos. Describe el resultado con palabras concretas: claridad, continuidad, resonancia.'],
    lab:['Toca el estudio seco y con voces equilibradas.','Repite destacando la voz superior y añade pedal según la armonía.','Compara los resultados sin cambiar el volumen general del instrumento.'],
    question:'¿Cómo conviene comparar dos decisiones de color?',answers:['Cambiando todas las variables a la vez','Mirando solo la puntuación de notas','Cambiando una variable y escuchando el resultado'],correct:2,explanation:'Una comparación controlada permite atribuir el cambio a una decisión concreta.',target:'Elegir y describir un balance y una resonancia adecuados al estilo.' },
  { id:'memory',stage:6,title:'Recordar más de una manera',category:'Memoria',pattern:'memory',study:'Puntos de entrada',bpm:52,
    paragraphs:['La memoria musical combina oído, comprensión armónica, imagen de la partitura y movimientos. Depender solo de la cadena motora puede dificultar continuar si se rompe un enlace.','Divide la pieza en puntos de entrada independientes. Empieza por secciones distintas, canta líneas y explica las armonías sin tocar. Recuperar una sección desde varios indicios refuerza la seguridad.'],
    lab:['Elige tres puntos de entrada y nómbralos por su función.','Empieza en cada uno sin tocar lo anterior.','Canta la continuación y comprueba después en el teclado.'],
    question:'¿Qué mejora la recuperación después de una interrupción?',answers:['Tener puntos de entrada y varios tipos de memoria','Repetir únicamente desde el principio','Confiar solo en la velocidad de los dedos'],correct:0,explanation:'Los puntos de entrada y las referencias auditivas y armónicas ofrecen caminos de recuperación.',target:'Reanudar desde diferentes secciones sin depender de una cadena única.' },
  { id:'deliberate-practice',stage:7,title:'Diseñar una sesión útil',category:'Práctica profesional',pattern:'diagnostic',study:'Un estudio, tres decisiones',bpm:54,
    paragraphs:['Una sesión eficaz parte de un problema concreto y una hipótesis: qué ocurre, por qué puede ocurrir y qué cambio probarás. Alterna trabajo focalizado, integración y una pasada de comprobación.','Para tus 60–120 minutos diarios, combina técnica breve, repertorio, lectura u oído y revisión, con descansos. El volumen de práctica no sustituye su calidad. Registra un objetivo verificable y revisa si el resultado mejora de una sesión a otra.'],
    lab:['Elige un fragmento y anota un problema concreto.','Prueba una estrategia: manos separadas, ritmo variado o reducción armónica.','Haz una toma de comprobación y decide el siguiente objetivo.'],
    question:'¿Cuál es un objetivo de práctica verificable?',answers:['Tocar mejor sin definir qué cambiar','Mantener el pulso en los compases 3–6 a 60 BPM','Repetir toda la obra veinte veces'],correct:1,explanation:'Un fragmento, una conducta y un tempo hacen el objetivo observable.',target:'Una sesión con diagnóstico, estrategia y comprobación.' },
  { id:'programme',stage:7,title:'Construir un programa',category:'Repertorio profesional',pattern:'programme',study:'Tres miniaturas, un programa',bpm:58,
    paragraphs:['Un programa combina duración, contraste, exigencia, estilo y contexto. Seleccionar repertorio implica conocer lo que puedes preparar con calidad en el tiempo disponible, no reunir solo las obras más difíciles.','Alterna piezas de mantenimiento con obras nuevas. Programa ensayos completos y transiciones entre obras. La preparación profesional requiere revisión musical y técnica externa; completar esta ruta no acredita por sí solo un nivel profesional.'],
    lab:['Elige tres piezas contrastantes y estima su duración real.','Anota dificultades y un calendario de preparación razonable.','Ensaya el programa con pausas y entradas completas.'],
    question:'¿Qué debe equilibrar un programa?',answers:['Solo la dificultad máxima','Únicamente el número de páginas','Duración, contraste, contexto y preparación real'],correct:2,explanation:'Un programa se diseña para un contexto y una interpretación sostenible de calidad.',target:'Planificar un programa coherente y revisarlo con un profesor o mentor.' },
  { id:'performance',stage:7,title:'Del ensayo a la toma completa',category:'Interpretación en público',pattern:'performance',study:'Una toma de principio a fin',bpm:60,
    paragraphs:['Interpretar una pieza completa necesita atención a la continuidad, las transiciones y la recuperación ante errores. Ensayar siempre con interrupciones no prepara exactamente la experiencia de tocar ante alguien.','Alterna sesiones de detalle con simulaciones de una sola toma. Define antes cómo empezar, dónde respirar y cómo continuar si aparece un fallo. Después evalúa musicalidad y continuidad, además de las notas.'],
    lab:['Prepara un inicio silencioso y decide el tempo interiormente.','Toca el estudio completo sin detenerte a corregir.','Revisa una grabación y escoge solo dos aspectos para la siguiente toma.'],
    question:'¿Qué entrena una simulación de concierto?',answers:['La continuidad y la recuperación durante una toma','Solo el número de repeticiones','La eliminación de toda incertidumbre'],correct:0,explanation:'Una toma completa permite ensayar continuidad, transiciones y recuperación.',target:'Mantener el discurso en una toma y analizarlo después.' },
  { id:'collaboration',stage:7,title:'Escuchar a otra persona',category:'Música de conjunto',pattern:'ensemble',study:'Pregunta y respuesta',bpm:56,
    paragraphs:['Tocar con otras personas exige escuchar respiraciones, entradas, balance y flexibilidad compartida. Conocer tu parte es necesario, pero también lo es comprender qué sucede en las demás.','El estudio alterna preguntas y respuestas entre registros. Sirve como preparación individual; no simula la comunicación con otro músico. Para trabajar esa capacidad necesitas ensayar con una persona y acordar señales y criterios.'],
    lab:['Canta una línea mientras tocas la otra.','Identifica dónde darías una entrada o una respiración.','Ensaya un fragmento real con otra persona y revisad el balance juntos.'],
    question:'¿Qué añade la música de conjunto al trabajo individual?',answers:['Tocar siempre a un volumen mayor','Escucha y decisiones compartidas en tiempo real','Evitar conocer la otra parte'],correct:1,explanation:'El conjunto necesita atención y adaptación mutua, además del dominio de cada parte.',target:'Escuchar, dar entradas y ajustar el balance con otro músico.' },
  { id:'recording-review',stage:7,title:'Tu criterio como intérprete',category:'Evaluación profesional',pattern:'finale',study:'Cuaderno de interpretación',bpm:54,
    paragraphs:['Una evaluación completa considera ritmo, precisión, sonido, fraseo, estilo, forma, lectura y presencia. Las métricas MIDI aportan información parcial: no sustituyen una escucha informada ni una valoración presencial.','Conserva tomas comparables y escribe observaciones concretas con marcas de tiempo. Revisa con un profesor o músico experimentado las decisiones técnicas y estilísticas. El objetivo final es desarrollar criterio para seguir aprendiendo de forma autónoma.'],
    lab:['Graba una interpretación de una pieza completa fuera de la app.','Valora continuidad, balance, articulación y dirección de las frases con ejemplos.','Contrasta tu valoración con una revisión externa y prepara el siguiente plan.'],
    question:'¿Qué demuestra una puntuación MIDI alta?',answers:['Que toda la interpretación es profesional','Que la postura y el fraseo son correctos','Que ciertos aspectos medidos, como las notas, han salido bien'],correct:2,explanation:'La puntuación mide lo que el sistema observa; la evaluación musical completa requiere más evidencias.',target:'Una autoevaluación documentada y contrastada con revisión externa.' },
];

const seq=(pitches,step=1,hand='right',offset=0,duration=step*.85)=>pitches.map((pitch,i)=>({pitch,beat:offset+i*step,duration,hand}));
const repeat=(list,n)=>Array.from({length:n},()=>list).flat();
function studyNotes(pattern) {
  const major=[60,62,64,65,67,69,71,72,71,69,67,65,64,62,60,60];
  switch(pattern) {
    case 'legato': return seq(repeat([60,62,64,65,67,65,64,62],4));
    case 'major': return [...seq(major),...seq(major.map(n=>n-12),1,'left',16)];
    case 'eighths': return [...seq([60,62,64,65],1),...seq(repeat([67,65,64,62],3),.5,'right',4),...seq([60,64,62,60],1,'right',10)];
    case 'syncopation': return [...seq(repeat([64,67,65,69],4),1,'right',.5,.8),...seq(repeat([48,53,55,48],4),1,'left')];
    case 'gmajor': return seq(repeat([55,57,59,60,62,64,66,67,66,64,62,60,59,57,55,55],2),.5);
    case 'inversions': return [0,4,8,12,16,20].flatMap((beat,i)=>([[60,64,67],[64,67,72],[67,72,76]][i%3]).map(pitch=>({pitch,beat,duration:3,hand:'right'})));
    case 'intervals': return seq(repeat([60,64,60,67,62,66,62,69],4));
    case 'minor': return seq([57,59,60,62,64,65,67,69,57,59,60,62,64,65,68,69,57,59,60,62,64,66,68,69,67,65,64,62,60,59,57,57],.5);
    case 'wide-arpeggio': return [...seq(repeat([48,52,55,60,64,67,72,67,64,60,55,52],4),.5),...seq(repeat([36,43,48,43],6),1,'left')];
    case 'alberti': return [...seq(repeat([48,55,52,55,53,60,57,60,55,62,59,62,48,55,52,55],4),.5,'left'),...seq(repeat([72,71,69,67,65,64,62,60],4),1)];
    case 'voicing': return Array.from({length:24},(_,i)=>[60+i%3,64+i%3,72+[0,2,4,5,4,2][i%6]].map(pitch=>({pitch,beat:i*2,duration:1.6,hand:'right'}))).flat();
    case 'aba': return seq([...major,...major.map(n=>n+5),...major],.5);
    case 'counterpoint': return [...seq(repeat([72,71,69,67,69,71,72,74],6),.5),...seq(repeat([48,50,52,53,55,53,52,50],3),1,'left')];
    case 'two-three': return [...seq(repeat([60,64,67],8),2/3),...seq(repeat([48,55],8),1,'left')];
    case 'chromatic': return seq([...Array.from({length:25},(_,i)=>48+i),...Array.from({length:25},(_,i)=>72-i)],.5);
    case 'modulation': return [0,4,8,12,16,20,24,28].flatMap((beat,i)=>[[48,60,64,67],[53,60,65,69],[55,59,62,67],[48,60,64,67],[55,59,62,67],[50,57,62,66],[55,59,62,67],[43,55,59,62]][i].map((pitch,j)=>({pitch,beat,duration:3,hand:j===0?'left':'right'})));
    case 'sight': return [...seq([60,64,62,65,64,67,65,69,67,64,65,62,64,60,62,60]),...seq([48,53,55,48],4,'left')];
    case 'three-four': return [...seq(repeat([60,64,67,72],8),.75),...seq(repeat([48,55,52],8),1,'left')];
    case 'octaves': return seq(repeat([60,62,64,65,67,65,64,62],4)).flatMap(n=>[n,{...n,pitch:n.pitch+12}]);
    case 'leaps': return [...seq(repeat([36,60,43,67,41,65,48,72],4),1,'left'),...seq(repeat([76,74,72,71],8),1)];
    case 'ornaments': return seq(repeat([64,65,64,62,64,67,65,64,62,64,62,60,62,65,64,60],4),.25);
    case 'pedal': return [0,4,8,12,16,20,24,28].flatMap((beat,i)=>[[48,60,64,67],[45,57,60,64],[41,53,57,60],[43,55,59,62]][i%4].map((pitch,j)=>({pitch,beat,duration:3.5,hand:j===0?'left':'right'})));
    case 'rubato': return [...seq(repeat([72,71,69,67,65,64,62,60],4)),...seq(repeat([48,45,53,55],2),4,'left',0,3)];
    case 'voice-leading': return [0,4,8,12,16,20,24,28].flatMap((beat,i)=>[[48,60,64,67],[45,60,64,69],[53,60,65,69],[55,59,62,67]][i%4].map((pitch,j)=>({pitch,beat,duration:3.5,hand:j===0?'left':'right'})));
    case 'development': return seq(Array.from({length:8},(_,i)=>[60,62,64,62,60,64,67,64].map(n=>n+[0,2,4,5,7,5,2,0][i])).flat(),.5);
    case 'colour': return Array.from({length:12},(_,i)=>[48,60,64,67,72].map((pitch,j)=>({pitch,beat:i*4,duration:3.5,hand:j<2?'left':'right'}))).flat();
    case 'memory': return seq([major,major.map(n=>n+5),major.map(n=>n+7),major].flat(),.5);
    case 'diagnostic': return [...studyNotes('alberti'),...seq(repeat([72,74,76,77,79,77,76,74],4),.5,'right',32)];
    case 'programme': return [...seq(major,.5),...seq(major.map(n=>n+5),.75,'right',8),...seq(major.map(n=>n+12),.5,'right',20)];
    case 'performance': return [...seq(repeat(major,8),.5),...seq(repeat([48,53,55,48],8),2,'left',0,1.8)];
    case 'ensemble': return Array.from({length:8},(_,i)=>seq(i%2?[48,52,55,52]:[72,76,79,76],.5,i%2?'left':'right',i*2)).flat();
    case 'finale': return [...seq(repeat([...major,...major.map(n=>n+7)],4),.5),...seq(repeat([36,43,48,43,41,48,53,48],8),1,'left')];
    default:return seq(major);
  }
}

const introStages={position:0,keyboard:0,pulse:0,hands:0,reading:0,intervals:1,chords:1,pedal:1};
const order=['position','keyboard','pulse','hands','reading','intervals','major-scale','legato','chords','pedal',...additions.filter(l=>l.stage>=2).map(l=>l.id)];
export const LESSONS = [...INTRO_LESSONS.map(l=>({...l,stage:introStages[l.id],target:'Comprender la explicación y probarla despacio en el teclado.'})),...additions.map(l=>({...l,duration:'10–20 min',icon:l.category.includes('Ritmo')?'pulse':'notes',exercise:'drill-'+l.id}))]
  .sort((a,b)=>order.indexOf(a.id)-order.indexOf(b.id)).map((l,i)=>({...l,unit:String(i+1).padStart(2,'0')}));
export const SONGS = [
  ...INTRO_SONGS.map(s=>({...s,stage:['arpeggio','waltz'].includes(s.id)?1:0,kind:'exercise'})),
  ...additions.map(l=>({id:'drill-'+l.id,title:l.study,composer:'Estudio original · Ivory',kind:'exercise',lessonId:l.id,stage:l.stage,level:l.stage+1,color:['sage','rose','sand','lilac','blue'][l.stage%5],minutes:l.stage>=5?15:8,bpm:l.bpm,beatsPerBar:4,description:l.target,instructions:l.lab,notes:studyNotes(l.pattern)})),
];
